  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9a215ba3-28e1-4619-b1c4-b08f2e377c34', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$‘कर चले हम फ़िदा’ कविता के केंद्रीय भाव को विस्तार से समझाइए और बताइए कि यह किस प्रकार देशभक्ति और बलिदान की भावना को व्यक्त करती है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-47-097Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9a215ba3-28e1-4619-b1c4-b08f2e377c34', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कविता में सैनिकों की अंतिम इच्छा और उनके बलिदान के महत्व का विश्लेषण कीजिए। उन्होंने आने वाली पीढ़ी को क्या संदेश दिया है?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-47-097Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9a215ba3-28e1-4619-b1c4-b08f2e377c34', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$‘साँस थमती गई, नब्ज़ जमती गई, फिर भी बढ़ते कदम को न रुकने दिया’ और ‘कट गए सर हमारे तो कुछ ग़म नहीं, सर हिमालय का हमने न झुकने दिया’ पंक्तियों के माध्यम से कवि ने सैनिकों के अदम्य साहस और देशप्रेम को कैसे दर्शाया है? विस्तार से चर्चा कीजिए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-47-097Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
