  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '9a215ba3-28e1-4619-b1c4-b08f2e377c34', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कविता में सैनिकों की मनःस्थिति का चित्रण किस प्रकार किया गया है? वे किन भावनाओं से ओत-प्रोत होकर अपना बलिदान देते हैं?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-47-097Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
